<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Invoice extends Model {protected $guarded=[]; protected $casts=['subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2','paid'=>'decimal:2','balance'=>'decimal:2']; public function customer(){return $this->belongsTo(Customer::class);} public function job(){return $this->belongsTo(Job::class);} public function items(){return $this->hasMany(InvoiceItem::class);} public function payments(){return $this->hasMany(Payment::class);} }
